import { afterEach, describe, expect, it, vi } from 'vitest'
import { inquireStatement } from './statementInquiryClient'

describe('inquireStatement', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('builds endpoint and sends bearer token header', async () => {
    const fetchSpy = vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(
        JSON.stringify({
          sortCode: '123456',
          accountNumber: '00000001',
          period: '202607',
          summary: {
            periodFrom: '20260701',
            periodTo: '20260731',
            openingBalance: 500,
            totalCredits: 100,
            totalDebits: 10,
            closingBalance: 590,
            transactionCount: 1,
          },
          entries: [],
        }),
        {
          status: 200,
          headers: {
            'content-type': 'application/json',
            'X-Correlation-ID': 'corr-1',
          },
        },
      ),
    )

    const result = await inquireStatement({
      sortCode: '123456',
      accountNumber: '00000001',
      period: '202607',
    })

    expect(fetchSpy).toHaveBeenCalledWith(
      '/api/v1/accounts/123456/00000001/statements/202607',
      expect.objectContaining({
        headers: expect.objectContaining({
          Authorization: 'Bearer valid-inqacc-inquirer-token',
        }),
      }),
    )
    expect(result.type).toBe('success')
  })

  it('returns backend-error for authorization failure', async () => {
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(
      new Response(
        JSON.stringify({
          code: 'ERR-003',
          message: 'Forbidden',
          correlationId: 'corr-403',
        }),
        {
          status: 403,
          headers: {
            'content-type': 'application/json',
            'X-Correlation-ID': 'corr-403',
          },
        },
      ),
    )

    const result = await inquireStatement({
      sortCode: '123456',
      accountNumber: '00000001',
      period: '202607',
    })

    expect(result.type).toBe('backend-error')
    if (result.type === 'backend-error') {
      expect(result.status).toBe(403)
      expect(result.error.code).toBe('ERR-003')
    }
  })
})

  test('renders retrieval-failure business outcome from backend response', async ({ page }) => {
    await page.goto('http://localhost:5173/customer-accounts')

    await page.getByLabel('Customer Number').fill('0000000200')
    await page.getByRole('button', { name: 'Inquire' }).click()

    await expect(page.getByText('Account retrieval failed. Please retry later.')).toBeVisible()
    const customerSummary = page.getByLabel('Customer Summary')
    await expect(customerSummary.getByText('0000000200')).toBeVisible()
    await expect(page.getByText(/^2$/)).toBeVisible()
    await expect(page.getByText('Customer not found')).not.toBeVisible()
    await expect(page.getByRole('heading', { name: 'Backend Error' })).not.toBeVisible()
    await expect(page.getByText('Service unavailable due to infrastructure failure')).not.toBeVisible()
  })
})

@Test
void shouldReturnOpenStageBusinessFailureWhenRepositorySignalsOpenFailure() {
    when(repository.findByCustomerNumber("0000000200"))
            .thenThrow(RetrievalStageFailureException.openStage("0000000200"));

    AccountRelationshipResponse response = service.inquire("0000000200");

    assertThat(response.legacyStatus().success()).isEqualTo("N");
    assertThat(response.legacyStatus().failCode()).isEqualTo("2");
    assertThat(response.legacyStatus().customerFound()).isEqualTo("Y");
    assertThat(response.customerNumber()).isEqualTo("0000000200");
    assertThat(response.numberOfAccounts()).isZero();
    assertThat(response.accounts()).isEmpty();
}

